i/dsh-settings\": \"^0.1.0-rc.7 || ^0.1.1-rc.2 || ^0.1.2-alpha.2 || ^0.2.0-rc.1 || ^0.2.1-alpha.3 || ^0.2.1-rc.1\",\n    \"@deepseek-ai/schemastery\": \"^3.18.1\"\n  },\n  \"dsh\": {\n    \"bundle\": {\n      \"patch\": \"./cordis.patch.yml\"\n    },\n    \"client\": {\n      \"inject\": [\n        \"@deepseek-ai/dsh-client-locale\",\n        \"@deepseek-ai/dsh-client-ui-settings\",\n        \"@deepseek-ai/dsh-client-ui-theme\"\n      ],\n      \"platform\": \"web\"\n    }\n  },\n  \"exports\": {\n    \".\": {\n      \"types\": \"./lib/types/index.d.ts\",\n      \"default\": \"./lib/index.js\"\n    },\n    \"./update-api-v1\": {\n      \"types\": \"./lib/types/update-api-v1.d.ts\",\n      \"default\": \"./lib/update-api-v1.js\"\n    },\n    \"./client\": \"./client/client.js\",\n    \"./cordis.patch.yml\": \"./cordis.patch.yml\",\n    \"./package.json\": \"./package.json\",\n    \"./locale/*.json\": \"./locale/*.json\"\n  },\n  \"files\": [\n    \"assets/logo.svg\",\n    \"locale\",\n    \"lib\",\n    \"src\",\n    \"client\",\n    \"UPDATE-API-V1.md\",\n    \"cordis.patch.yml\",\n    \"LICENSE\"\n  ],\n  \"devDependencies\": {\n    \"@deepseek-ai/cordis\": \"^4.0.1\",\n    \"@deepseek-ai/dsh-client-runtime\": \"^0.1.0-rc.7\",\n    \"@deepseek-ai/dsh-client-ui-primitives\": \"^0.1.0-rc.6\",\n    \"@deepseek-ai/dsh-client-ui-settings-plugins\": \"^0.1.0-rc.7\",\n    \"@deepseek-ai/dsh-invariants\": \"^0.1.0-rc.6\",\n    \"@deepseek-ai/dsh-settings\": \"^0.1.0-rc.7\",\n    \"@deepseek-ai/schemastery\": \"^3.18.1\",\n    \"@testing-library/react\": \"^16.3.2\",\n    \"@types/js-yaml\": \"^4.0.9\",\n    \"@types/node\": \"^26.2.0\",\n    \"@types/react\": \"~18.3.1\",\n    \"@types/react-dom\": \"~18.3.1\",\n    \"jsdom\": \"^29.1.1\",\n    \"lightningcss\": \"^1.33.0\",\n    \"marked\": \"^18.0.10\",\n    \"playwright\": \"^1.62.1\",\n    \"react\": \"^18.3.1\",\n    \"react-dom\": \"~18.3.1\",\n    \"tsdown\": \"^0.22.14\",\n    \"typescript\": \"^7.0.2\",\n    \"vite